mapper.select:
SELECT OP.*, CV.ConstrValDesc AS payTypeName
FROM shopion.tOrdOrderPay OP
LEFT OUTER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cPayType') CV ON OP.PayType = CV.ConstrVal
WHERE OP.OrderNo = #{orderNo}
AND OP.PayNo = #{payNo}

mapper.update:
UPDATE shopion.tOrdOrderPay SET
    PayType = #{payType}, PayDate = #{payDate}, PayAmt = #{payAmt}, PayFee = #{payFee},
    CardComp = #{cardComp}, ApprovNo = #{approvNo}, ApprovDate = #{approvDate},
    ReciptBank = #{reciptBank}, ReciptName = #{reciptName}, ReciptAccnt = #{reciptNo}, ReciptDate = #{reciptDate},
    PgCode = #{pgCode}, PgOrderCode = #{pgOrderNo}, PgTradeNo = #{pgTradeNo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
AND PayNo = #{payNo}

UPDATE shopion.tOrdOrderPay SET
    ReciptBank = #{reciptBank}, ReciptName = #{reciptName}, ReciptNo = #{reciptNo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}

UPDATE shopion.tOrdOrderPay SET
    ReciptBank = #{reciptBank}, ReciptName = #{reciptName}, ReciptNo = #{reciptNo},
    ReciptDate = NOW(),
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
